-- Owner-requested brand correction. Only the 3dyanimda tenant is changed.
-- Existing runtime sources remain tenants, site_settings, seo_meta and landing_pages.
BEGIN;
SET LOCAL TIME ZONE 'UTC';
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DO $$ BEGIN
 IF (SELECT count(*) FROM public.tenants WHERE slug='3dyanimda' AND domain='3dyanimda.com' AND status='active') <> 1 THEN RAISE EXCEPTION 'Expected active 3dyanimda tenant not found'; END IF;
END $$;
UPDATE public.tenants SET name='3D Yanımda' WHERE slug='3dyanimda' AND domain='3dyanimda.com';
UPDATE public.site_settings SET value=value || '{"business_name":"3D Yanımda","business_alternate_names":"3dyanımda\n3dyanimda.com","business_description":"3D Yanımda, İstanbul Ataşehir’de 3D baskı, 3D tarama ve 3D modelleme hizmetleri sunar. Prototip, özel parça ve hobi projelerinde dosya veya numuneden başlayarak üretim kapsamını birlikte belirler.","about_title":"3D Yanımda ile fikirden üretime.","about_text":"3D Yanımda, İstanbul’un Ataşehir ilçesinde 3D baskı, 3D tarama ve 3D modelleme projelerini değerlendirir. Örnek Mahallesi, Bestekar Sokak No: 17’deki çalışma noktamıza ziyaretler randevuyla yapılır. Bir ürün ekibinin prototipi, üretimde ihtiyaç duyulan özel parça veya kişisel bir hobi fikriyle başlayabilirsiniz.\n\nÖnce parçanın kullanım amacını, temel ölçülerini ve beklentinizi konuşuruz. Hazır modeliniz varsa dosyayı inceleriz; fiziksel örnek, eskiz veya fotoğrafla geliyorsanız gereken tarama ve modelleme çalışmalarını belirleriz. Malzeme, üretim yöntemi, adet, revizyon ve ek işlemler teklif kapsamına birlikte alınır.\n\nKapsam ve fiyat onaylandıktan sonra üretim planı netleşir. Kargo, kurye veya randevuyla elden teslim seçeneği; parça, ambalaj ve hedef adresle birlikte değerlendirilir. Mevcut dosyayı değiştireceğiniz ya da numuneyi tekrar üreteceğiniz işlerde onaylı revizyonu ve kontrol beklentisini birlikte kaydederiz."}'::jsonb,updated_at=now() WHERE tenant_id=(SELECT id FROM public.tenants WHERE slug='3dyanimda') AND key='contact_info';
UPDATE public.site_settings SET value=jsonb_set(value,'{lead_tr}',to_jsonb('3D Yanımda, İstanbul Ataşehir’de 3D baskı, 3D tarama ve 3D modelleme hizmetleri sunar. Fabrika parçasından hobi projenize; dosyanız, numuneniz veya fikrinizle başlayın.'::text)),updated_at=now() WHERE tenant_id=(SELECT id FROM public.tenants WHERE slug='3dyanimda') AND key='hero_content';
UPDATE public.site_settings SET value=jsonb_set(value,'{alt}','"3D Yanımda"'::jsonb),updated_at=now() WHERE tenant_id=(SELECT id FROM public.tenants WHERE slug='3dyanimda') AND key IN ('logo_icon','logo_icon_light','logo_wordmark','logo_wordmark_light','logo_text','logo_text_light','favicon','apple_touch_icon','og_image','organization_logo');
INSERT INTO public.seo_meta(tenant_id,path,title_tr,description_tr,noindex)
SELECT t.id,v.path,v.title,v.description,false FROM jsonb_to_recordset('[{"path":"/","title":"3D Yanımda | Ataşehir’de 3D Baskı, Tarama ve Modelleme","description":"İstanbul Ataşehir’de 3D baskı, tarama ve modelleme. Prototip, özel parça veya hobi projenizi 3D Yanımda ile değerlendirin; dosyanızı paylaşarak teklif isteyin."},{"path":"/3d-baski","title":"3D Baskı ve Prototip Üretimi | 3D Yanımda","description":"Modelinizden prototip, özel parça veya hobi ürünü için 3D baskı teklifi alın. Dosya, malzeme, adet ve teslimat kapsamını Ataşehir’de birlikte değerlendirelim."},{"path":"/3d-tarama","title":"3D Tarama ve Dijitalleştirme | 3D Yanımda","description":"Fiziksel numunenizi dijital geometriye taşıyın. Fotoğraf, ölçü ve kullanım amacınızla 3D tarama, yerinde çalışma ve CAD ihtiyacınızı değerlendirelim."},{"path":"/3d-modelleme","title":"3D Modelleme ve Ürün Tasarımı | 3D Yanımda","description":"Eskiz, ölçü veya numuneden 3D model geliştirin. Üretim amacı, revizyonlar ve teslim formatını belirleyerek modelleme projeniz için teklif isteyin."},{"path":"/hakkimizda","title":"Hakkımızda | 3D Yanımda","description":"Ataşehir’deki 3D Yanımda’yı tanıyın. Dosya ve numune değerlendirmesinden modelleme, üretim onayı ve teslimata kadar çalışma yaklaşımımız."},{"path":"/iletisim","title":"İletişim ve Atölye Randevusu | 3D Yanımda","description":"3D Yanımda’ya ulaşın: Örnek Mahallesi, Bestekar Sokak No: 17, Ataşehir. Projenizi paylaşmak, numune göndermek veya atölye randevusu için iletişime geçin."}]'::jsonb) AS v(path text,title text,description text) JOIN public.tenants t ON t.slug='3dyanimda'
ON CONFLICT(tenant_id,path) DO UPDATE SET title_tr=EXCLUDED.title_tr,description_tr=EXCLUDED.description_tr,updated_at=now()
WHERE seo_meta.tenant_id='10000000-0000-4000-8000-000000000001'
  AND seo_meta.tenant_id=EXCLUDED.tenant_id AND seo_meta.path=EXCLUDED.path;
-- Reviewed landing updates retain the existing publication guard and row status.
DO $brand_pages$
DECLARE
  entry jsonb;
  current_row public.landing_pages%ROWTYPE;
  target_doc jsonb;
  current_hash text;
  target_hash text;
  review_report jsonb := '{"policy":"global-originality-v1","result":"pass","reviewer":"Codex (AI, owner-delegated)","humanReviewPerformed":false,"reviewedAt":"2026-10-21T21:57:54.759Z","baseCommit":"112c0769195929f78666c4519f60a21a0aee18e7","sourceHash":"5703c39af22d462a85c5bac8016f7ca545e29c99791f965da98833a7f9f345d0","sourceFileCount":587,"scope":"Bounded review of the 3D Yanımda name, CMS profile, three service pages, two local pages, entity links and transient tenant metadata. Historical unchanged content and visual evidence retain their original dates.","checks":{"renderedText":"Reviewed all five edited page payloads and business-profile copy. They describe verified workshop contact facts, project-dependent estimates and actual supported model formats; no ranking, deadline or certification promises were added.","tenantIsolation":"JSON comparison confirms that authored records for the other brands are byte-for-byte unchanged. Profile and metadata hooks discard state from a previous tenant or route while new data is loading.","imageProvenance":"No public asset or model bytes changed. Brand asset alt text is updated only for 3dyanimda.","localEvidence":"The workshop address matches the live owner-managed contact_info. Kadıköy describes delivery from Ataşehir, not a separate branch. Existing locality source references are retained.","seoGeoParity":"Brand display name and alternate names are consistent in catalog, CMS seed and Organization/WebSite graphs. About/Contact entity links refer to the same organization. No unverified social or map URL is added.","publicationGate":"The seed is bounded to five reviewed landing-page patches, matches the observed baseline or an already-applied target, and records the exact resulting payload hash before each update. Existing publication and validation triggers stay enabled. Both conflict-update clauses also explicitly require the verified 3dyanimda tenant ID and matching record keys."},"validation":{"applicationTests":220,"technicalContracts":72,"typecheck":"pass","productionBuild":"pass","originality":{"records":800,"result":"pass"},"databaseIntegration":"pass: actual publication/content/date triggers; exact approvals; other-tenant preservation; noindex/contact preservation; repeatability; concurrent-edit rejection; explicit conflict-update tenant predicates"},"limitations":["The current Supabase connector accepts reads but mutations returned Invalid or expired requestState; no CMS write or frontend deployment is claimed.","Cloudflare dashboard requires sign-in in this browser; production build error details have not been inspected.","This is a bounded AI source/content review with unit and contract evidence; no fresh full-site visual crawl or human/legal review is claimed.","Verified Google Business/social-profile links and Search Console canonical/indexing evidence are still unavailable."]}'::jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(610031601);
  FOR entry IN SELECT value FROM jsonb_array_elements('[{"path":"/3d-baski","expected_payload_hash":"98795703a2d35e88fec66c537eeca56e","patch":{"title":"Ürün geliştirme için 3D baskı","summary":"Bir ürün fikrini toplantıda gösterilecek objeden montaj denemesinde kullanılacak prototipe taşıyın. İlk numunenin hangi tasarım kararını doğrulayacağını birlikte belirleyelim.","sections":[{"body":"Elde tutuşu görmek için hazırlanan bir gövdeyle elektronik yerleşimini denemek için hazırlanan gövdenin ayrıntıları aynı olmayabilir. Projenizin bir sonraki kararını anlatın: boyut, düğme konumu, kapak erişimi veya bağlantı uyumu. Numune kapsamını bu kararı görünür kılacak şekilde oluşturalım.","title":"İlk baskı hangi soruya cevap verecek?"},{"body":"Alternatif tasarımları ayrı kodlarla paylaşmanız karşılaştırmayı kolaylaştırır. Örneğin iki kapak seçeneğinde yalnızca değişen tırnakları işaretleyin; ortak gövde dosyasını ayrıca belirtin. Denemeden çıkan bulguları onaylanan revizyona bağlayarak sonraki üretimde hangi çizimin esas alınacağını netleştirebiliriz.","title":"Tek dosyada kaybolmayan revizyonlar"},{"body":"Hedef dış ölçüyü, kullanılacak bileşenleri ve numuneyi inceleyecek kişinin beklentisini talebe ekleyin. Sunum parçasında görünen yüzeyler öncelikli olabilir; montaj prototipinde karşı parçanın referansları önem kazanır. Malzeme ve yüzey tercihini projenin bu aşamasına göre değerlendirelim.","title":"Ürün ekibinden gereken bilgiler"},{"body":"Prototipi test ederken yalnızca “oldu” veya “olmadı” sonucu tutmayın. Hangi yüzeyin temas ettiğini, hangi ölçünün değişmesi gerektiğini ve parçanın hangi kullanımda zorlandığını işaretleyin. Aynı parçanın iki revizyonunu birlikte sipariş edecekseniz dosya adlarını ayrı tutun. Böylece sonraki baskı, önceki denemenin ölçülebilir sonucuna dayanır.","title":"Bir sonraki revizyona veri bırakın"},{"title":"Baskı talebine hangi dosyayla başlayabilirsiniz?","body":"STL, OBJ, 3MF, STEP/STP veya IGES/IGS modelinizi teklif ekranında açabilirsiniz; dosya başına sınır 20 MB’tır. Önizlemede ölçü birimini ve dış boyutları kontrol edin, istediğiniz adedi ve parçanın nerede kullanılacağını yazın. Hazır modeliniz yoksa fotoğraf, eskiz veya numuneyle modelleme ihtiyacını birlikte değerlendirebiliriz."},{"title":"Ön tahminden onaylı üretim teklifine","body":"Teklif ekranındaki anlık hesap, seçtiğiniz malzeme ve üretim ayarlarına bağlı bir ön tahmindir. Dosya hazırlığı, parçanın geometrisi, adet, son işlemler ve teslimat kapsamı incelendikten sonra nihai teklif belirlenir. Üretim ölçüsü, malzeme uygunluğu ve teslim tarihi proje özelinde teyit edilir; onayınızdan sonra üretim planlanır."}],"faq":[{"a":"Aynı proje altında ayrı parça kodlarıyla değerlendirilebilir. Her numunenin amacı, adedi ve onay ölçütü talepte birbirinden ayrılmalıdır.","q":"Görünüş numunesi ile işlevsel prototip aynı siparişte olabilir mi?"},{"a":"Mevcut eskizi, temel ölçüleri ve test etmek istediğiniz özelliği paylaşın. Önce modelleme kapsamını, ardından fiziksel numune ihtiyacını belirleyebiliriz.","q":"Modelim henüz tamamlanmadıysa nasıl başlayabilirim?"},{"a":"Baskı numuneleri kargo, kurye veya elden teslim edilebilir; İstanbul dışındaki adreslere de kargo gönderimi yapılır. Örnek Mahallesi, Ataşehir’deki atölyeden teslim alacaksanız gelmeden randevu oluşturun. Numunenin adedi, ambalaj ihtiyacı ve hedef adresi teklif talebinize ekleyin.","q":"Prototipimi nasıl teslim alabilirim?"}],"editorial":{"answer":"3D baskı, dijital modelinizden fiziksel prototip veya düşük adetli parça üretmek için kullanılır. 3D Yanımda’da değerlendirme parçanın neyi doğrulayacağıyla başlar: görünüş, montaj, ergonomi veya işlev. Dosya, adet ve kullanım koşulları birlikte incelenerek malzeme, baskı yönü ve numune kapsamı belirlenir.","takeaways":["Görsel sunum ile çalışan prototipin kabul kriterleri farklıdır.","Fiyatı yalnızca gramaj değil; geometri, hazırlık ve son işlem de etkiler.","Tekrar üretim için dosya revizyonunu ve onaylı numuneyi birlikte kaydedin."],"comparison":{"rows":[["Görünüş modeli","Yüzey ve görsel bütünlük","Görünecek yüzeyler ve sunum amacı"],["Montaj prototipi","Eşleşen parçalar ve geçmeler","Kritik ölçüler, karşı parça ve montaj sırası"],["İşlev denemesi","Yük, sıcaklık ve hareket","Çalışma koşulu ve test yöntemi"],["Küçük seri","Onaylı revizyonun tekrarı","Numune onayı ve adet planı"]],"title":"Hangi prototip, hangi karar için?","columns":["İhtiyaç","Öncelik","Talebe eklenecek bilgi"]},"relatedPaths":["/rehber/prototip-maliyetini-ne-belirler","/rehber/3d-baski-mi-cnc-mi","/3d-modelleme","/cozumler/urun-gelistirme-prototipleri"]}}},{"path":"/3d-modelleme","expected_payload_hash":"a322cc49973688e886e625840d203cf0","patch":{"title":"3D modelleme ve ürün tasarımı: fikirden test edilebilir modele","summary":"Eskiz, ölçü ve kullanım senaryosunu birlikte ele alarak ilk ürün geometrisini geliştirin. Modelleme sürecinin çıktısını yalnızca görünüşe değil, prototiple sınanacak tasarım kararlarına bağlayın.","sections":[{"body":"Ürün kimin elinde, hangi ortamda ve hangi hareketle kullanılacak? Bu sorular gövde biçimi kadar düğme erişimini, açılma yönünü ve taşınabilirliği de etkiler. Referans görsellerinizi beğendiğiniz özelliklerle birlikte paylaşmanız tasarım niyetini anlaşılır kılar.","title":"Bir kullanım senaryosuyla başlayın"},{"body":"Hazır elektronik bileşen, bağlantı elemanı veya korunması gereken dış ölçü sabit girdi olabilir. Buna karşılık form, yüzey geçişi ve kapak düzeni geliştirilebilir alanlardır. İlk görüşmede bu sınırları ayırarak revizyonun nerede yapılabileceğini belirleyelim.","title":"Değişebilir bölgeleri ayırın"},{"body":"Ekrandaki modelde genel formu ve yerleşimi değerlendirdikten sonra kritik bölümleri numuneyle inceleyebilirsiniz. Elde tutuş veya geçme davranışı gibi konular fiziksel geri bildirim gerektirebilir. Sonraki düzenlemeleri aynı dosyanın üzerine belirsiz biçimde eklemek yerine sürümlendirelim.","title":"Dijital onaydan fiziksel denemeye"},{"body":"İlk tasarım görüşmesinde sabit kalacak ölçüleri ve değişebilecek özellikleri listeleyin. Bir kutuda kart ölçüsü sabitken kablo çıkışının yeri değişebilir. Bu ayrım, modelin nasıl kurulacağını etkiler. Kontrol görüntüsü, ölçü listesi ve fiziksel numune onayını farklı aşamalar olarak ele almak, yalnızca görüntü üzerinden verilmiş bir onayın üretim onayıyla karışmasını önler.","title":"Revizyonu yönetilebilir hale getirin"},{"title":"Modelleme talebinizin başlangıç paketi","body":"Eskiz, teknik resim, fotoğraf, temel ölçüler veya fiziksel numuneyle başlayabilirsiniz. Parçanın işlevini, değişmemesi gereken boyutları ve birlikte çalışacağı bileşenleri belirtin. Mevcut bir dosyanız varsa teklif ekranına ekleyin; yalnızca görselleştirme mi yoksa üretime hazırlık mı istediğinizi açıklayın."},{"title":"Revizyon, dosya teslimi ve fiyat kapsamı","body":"Teklif; mevcut referansların yeterliliği, geometrinin karmaşıklığı, ölçüm veya tarama gereksinimi, revizyon kapsamı ve teslim formatına göre hazırlanır. Düzenlenebilir CAD dosyası, baskı ağı ve görsel sunum aynı çıktı değildir. İhtiyaç duyduğunuz teslimleri ve onay adımlarını işe başlamadan birlikte belirleyelim."}],"faq":[{"a":"Referansın hangi özelliğini istediğinizi belirtmeniz gerekir. Kullanım hakkı, hedef ölçüler ve sizin ürününüze özgü değişiklikler modelleme kapsamına girmeden netleştirilir.","q":"Bir referans ürünün aynısını çizmeniz yeterli olur mu?"},{"a":"Dosyayı üretim, görselleştirme veya sonraki CAD düzenlemesi için kullanacağınızı yazın. Teslim formatı ve düzenlenebilirlik beklentisi buna göre kapsamlandırılır.","q":"Modelleme tesliminde hangi formatı istemeliyim?"},{"a":"Referans ürününüzü kargo veya kurye ile gönderebilir, randevu alarak elden getirebilirsiniz. Şehir dışındaki ekiplerle de kargo üzerinden numune alışverişi yapılabilir. Gönderiye ürün kodunu ve modelde değiştirilmesini istediğiniz özellikleri eklemek, örneği doğru çizim revizyonuyla eşleştirmeye yardımcı olur.","q":"Tasarım için fiziksel örneği nasıl ulaştırabilirim?"}],"editorial":{"answer":"3D modelleme; eskiz, teknik resim, ölçü veya tarama referansını üretilebilir dijital tasarıma dönüştürür. Ürün geliştirmede modelin dış görünüşü kadar montaj ilişkileri ve değiştirilebilir ölçüleri de önemlidir. Baskıya uygun ağ dosyası ile sonraki revizyonlarda düzenlenebilen CAD teslimi birlikte planlanabilir.","takeaways":["Dosyayı oluşturmak için mevcut referansları ve eksik ölçüleri ayırın.","Kritik bağlantılar ile yalnızca görsel olan detayları belirtin.","Teslim formatını üretim ve sonraki revizyon ihtiyaçlarına göre seçin."],"comparison":{"rows":[["Eskiz / fikir","Ölçülü tasarım geliştirme","Dış boyut ve işlev"],["Teknik resim","CAD model oluşturma","Eksik ölçü ve toleranslar"],["Fiziksel örnek","Ölçüm veya tarama destekli modelleme","Kopyalanacak ve değiştirilecek bölgeler"]],"title":"Tasarım başlangıç noktaları","columns":["Elinizdeki veri","Çalışma","İlk karar"]},"relatedPaths":["/3d-baski","/3d-tarama","/rehber/3d-baski-mi-cnc-mi"]}}},{"path":"/3d-tarama","expected_payload_hash":"5db089f85b332b58870637bc72700a4f","patch":{"title":"Ürün referanslarını dijitale taşıyan 3D tarama","summary":"Elinizdeki objeyi yeni tasarımın referansı yapmak için tarama kapsamını belirleyin. Dış formu görmek, mevcut ürüne oturan bir aksesuar geliştirmek ve CAD referansı oluşturmak farklı çıktılar gerektirir.","sections":[{"body":"Tarama talebine yalnızca objenin fotoğrafını değil, ona bağlı tasarım fikrini de ekleyin. Yeni bir muhafaza mevcut yüzeye oturacaksa temas bölgesini gösterin. Sunum için dijitalleştirilen bir obje söz konusuysa görünmesi gereken yüzeyleri ve kullanım ölçeğini açıklayın.","title":"Referans objenin projedeki rolü"},{"body":"Elde edilen yüzeyin doğrudan görüntülenmesi ile düzenlenebilir bir tasarım referansına dönüştürülmesi ayrı işlemlerdir. Dosyayı hangi yazılımda ve hangi amaçla kullanacağınızı baştan bilmek teslim biçimini belirlemeye yardımcı olur. CAD yeniden çizimi gerekiyorsa bunu tarama talebinde belirtin.","title":"Yüzey verisinden tasarım girdisine"},{"body":"Yaklaşık boyut, malzeme görünümü ve hareketli parçaların durumunu not edin. Sökülebilen kapaklar veya gizli yüzeyler varsa fotoğraflarda işaretleyin. Fiziksel gönderimden önce değerlendirme kapsamı ve numunenin geri dönüş şekli görüşülmelidir.","title":"Objeyi paylaşmadan önce"},{"body":"Nesnenin bütününü mü, montaja oturan belirli bir yüzeyini mi istediğinizi belirtin. Fotoğrafa bir cetvel eklemek ilk kapsam değerlendirmesine yardımcı olur; bu fotoğraf ölçüm raporu yerine geçmez. Renkli görünüm, geometrik ağ, CAD dosyası ve teknik rapor aynı teslim değildir. Beklenen dosya biçimi ve sonradan düzenleme ihtiyacını teklif aşamasında ayırın.","title":"Taramadan önce çıktı üzerinde anlaşın"},{"title":"Tarama teklifi için ilk paylaşım","body":"Objenin farklı açılardan çekilmiş fotoğraflarını, yaklaşık boyutlarını ve malzemesini paylaşın. Hangi yüzeylerin önemli olduğunu ve veriyi arşiv, yeniden tasarım ya da üretim için kullanacağınızı belirtin. Gönderilemeyecek bir parça için bulunduğu konumu, erişim koşullarını ve yerinde çalışma beklentinizi ekleyin."},{"title":"Tarama ve modelleme kapsamını ayrı netleştirelim","body":"Tarama fiyatı; geometriye, yüzeye erişime, hazırlığa, yerinde çalışma ihtiyacına ve istenen çıktıya göre değerlendirilir. Yüzey ağı temizliği ile düzenlenebilir CAD modelinin hazırlanması farklı çalışmalardır. Numuneyi göndermeden önce teslim formatı, geri gönderim ve takvim üzerinde anlaşalım."}],"faq":[{"a":"Kapsam, dijital verinin kullanım amacına bağlıdır. Yalnızca eşleşme bölgesi gereken bir aksesuar projesi ile tam obje sunumunun veri ihtiyacı farklıdır.","q":"Ürünün tüm yüzeylerinin taranması gerekli mi?"},{"a":"Referans olarak kullanılabilir; düzenlenebilir CAD geometrisine dönüşüm ayrı çalışma gerektirebilir. İstediğiniz düzenlemeleri teklif öncesinde tarif edin.","q":"Tarama dosyasını sonradan modellemede kullanabilir miyim?"},{"a":"Yerinde 3D tarama hizmeti veriyoruz. İncelenecek prototipin fotoğraflarını, yaklaşık boyutunu ve bulunduğu adresi paylaşın; erişim ve çekim koşullarını birlikte planlayalım. Atölyeye getirmeyi tercih ederseniz Örnek Mahallesi’ndeki çalışma noktası için önceden randevu alın.","q":"Prototipi taşımadan yerinde 3D tarama yaptırabilir miyim?"}],"editorial":{"answer":"3D tarama, elinizdeki nesnenin erişilebilen yüzeylerini dijital geometriye dönüştürür. Görsel arşiv, ölçü incelemesi ve yeniden tasarım farklı çıktılar gerektirir. Parçayı tekrar ürettirmek istiyorsanız tarama verisinin yanında düzenlenebilir CAD modeline ihtiyaç olup olmadığını başlangıçta belirlemek gerekir.","takeaways":["Parçanın büyüklüğünü ve yüzey özelliklerini fotoğraflarla gösterin.","Tarama ağı ile parametrik CAD modeli ayrı teslim kalemleridir.","Erişilemeyen iç yüzeyler için ek ölçüm veya söküm gerekebilir."],"comparison":{"rows":[["Dijital arşiv","Yüzey ağı","Eksik yüzey ve geometri temizliği"],["Yeniden tasarım","Referans ağ ve CAD çalışması","Kritik ölçüler ve tasarım niyeti"],["Mevcut modele kıyas","Hizalanmış veri","Referans sistemi ve karşılaştırma kapsamı"]],"title":"Tarama çıktısını kullanım amacına göre seçin","columns":["Amaç","Çıktı","Kontrol"]},"relatedPaths":["/3d-modelleme","/rehber/tarama-ve-tersine-muhendislik","/cozumler/urun-gelistirme-prototipleri"]}}},{"path":"/bolgeler/istanbul/atasehir/3d-baski","expected_payload_hash":"9119cd6cf0f52f36d618af0fd3c248e8","patch":{"title":"Ataşehir 3D baskı: atölye randevusu ve proje değerlendirme","summary":"Ataşehir Örnek Mahallesi’ndeki 3D Yanımda atölyesiyle dosyanız, numuneniz veya fikriniz üzerinden başlayın. Malzeme ve üretim kapsamını netleştirin; ziyaret, elden teslim veya gönderim planını teklif aşamasında belirleyin.","sections":[{"title":"Atölyeye gelmeden önce","body":"Parçayı kullanacağınız yeri, adedi ve kritik ölçüleri teklif talebinde belirtin. Fiziksel numune getirecekseniz birlikte çalıştığı bağlantı veya karşı parçanın da gerekli olup olmadığını önceden görüşelim. Teslim almaya gelmeden parçanın hazır olduğunu ve randevu saatini teyit edin."},{"body":"Kart yükselticilerinin referansını, bağlantıların dış erişimini ve kullanılacak kapak vidalarını belirtin. İnceleme için açık bırakılacak yüzeyi çizimde işaretleyin.","title":"Baskı teklifine eklenecek referanslar"},{"body":"Kartın oturma yönü, fişin takılabilmesi ve kablonun kapağa sıkışmaması sınanır. Baskıya sonradan açılan delikler ayrı not edilerek CAD düzeltmesine geri beslenir.","title":"Fiziksel denemede kaydedilecek bulgular"}],"faq":[{"q":"Ataşehir’de atölyeye doğrudan gelebilir miyim?","a":"Örnek Mahallesi, Bestekar Sokak No: 17 adresindeki atölye ziyareti ve elden teslim için önceden randevu alın. İletişim sayfasındaki telefon veya e-posta üzerinden ihtiyacınızı ve uygun zamanı paylaşabilirsiniz."},{"a":"İç düzeni gösterir; kapak kapanması ve dış görünüş için ayrı değerlendirme gerekir.","q":"Kapaksız numune nihai kabuğun yerini tutar mı?"},{"a":"Bunun uygunluğu ısı, elektriksel koşullar ve malzeme seçimiyle ayrıca değerlendirilmelidir; yerleşim numunesi bunu garanti etmez.","q":"Baskıda elektronik çalıştırılabilir mi?"}],"editorial":{"answer":"Ataşehir’de 3D baskı için modelinizi teklif ekranında paylaşabilir veya modeliniz yoksa eskiz ve numuneyle başlayabilirsiniz. 3D Yanımda’nın Örnek Mahallesi’ndeki atölyesinde ziyaretler randevuyla yapılır; malzeme, adet ve teslim planı projeniz incelendikten sonra netleşir.","sources":[{"url":"https://atasehir.gov.tr/tarihi-ve-cografi-yapisi","title":"Ataşehir Kaymakamlığı — Tarihi ve Coğrafi Yapısı"},{"url":"https://www.atasehir.bel.tr/atasehir/muhtarliklar","title":"Ataşehir Belediyesi — Mahalle ve Muhtarlıklar"},{"url":"https://zabita.ibb.gov.tr/birimlerimiz/anadolu-yakasi-zabita-mudurlugu/","title":"İBB Zabıta Daire Başkanlığı — Anadolu Yakası Zabıta Müdürlüğü"}],"takeaways":["Numune bırakmak veya elden teslim almak için randevu oluşturun.","Dosyanızın ölçü birimini, adedi ve kullanım amacını paylaşın.","Baskı, ek işlemler ve teslimat takvimini ayrı değerlendirin."],"relatedPaths":["/3d-baski","/bolgeler/istanbul","/cozumler/urun-gelistirme-prototipleri"]},"local_context":"3D Yanımda’nın çalışma noktası Örnek Mahallesi, Bestekar Sokak No: 17, Ataşehir’dedir. Numune bırakmak, proje görüşmek veya hazır parçayı teslim almak için gelmeden önce randevu alın. Model dosyanızı ve ihtiyacınızı önceden paylaşmanız görüşmede üretim kararlarına odaklanmamızı sağlar."}},{"path":"/bolgeler/istanbul/kadikoy/3d-baski","expected_payload_hash":"a2d833546a547bb96eeb6ba368c21a58","patch":{"title":"Kadıköy 3D baskı: dosya değerlendirme ve teslimat","summary":"Kadıköy için 3D baskı talebinizi model dosyası, adet ve kullanım amacıyla iletin. Malzeme seçimini, baskı ölçülerini ve kargo, kurye veya randevuyla elden teslim tercihinizi teklif aşamasında birlikte belirleyelim.","sections":[{"body":"Kadıköy’de teslim alacağınız mahalleyi ve açık adresi, ürünün gerekli olduğu günle birlikte belirtin. Baskı süresi geometri, malzeme ve adede bağlıdır; kurye veya kargo süresi buna eklenir. Aynı gün teslim gereksiniminiz varsa sipariş öncesinde uygunluk teyidi isteyin.","title":"Baskı ve taşıma süresini ayrı planlayın"},{"body":"Taşınan ürün prototipinde askı deliklerinin konumu, gövdenin duruşunu etkileyebilir. Baskı seti hazırlanırken bağlantı alternatifleri açıkça ayrılmalıdır.","title":"Örnek uygulama: askılı ürün gövdesi"},{"body":"Askı malzemesini, genişliğini ve gövdeye bağlanma yönünü paylaşın. İçeride temsili ağırlık kullanılacaksa konumunu yazın.","title":"Baskı teklifine eklenecek referanslar"},{"body":"Asılı duruş, bağlantıya erişim ve kıyafete temas eden köşeler incelenir. Baskı deliğinin çalışması bağlantının güvenli kullanım ömrünü kanıtlamaz.","title":"Fiziksel denemede kaydedilecek bulgular"}],"faq":[{"a":"Kurye ve kargo seçenekleri vardır. Paket ölçüsü, teslim adresi ve alıcı bilgisi paylaşılınca yöntem, ücret ve zaman planı netleştirilir; ilçeye göre otomatik bir süre verilmez.","q":"Kadıköy adresime kurye ile gönderim yapılıyor mu?"},{"a":"Üretimi tamamlanan parçayı Ataşehir’deki atölyeden randevuyla alabilirsiniz. Yola çıkmadan önce parçanın hazır olduğunu ve teslim saatini teyit edin.","q":"Baskıyı kendim teslim alabilir miyim?"},{"a":"Takma kolaylığı ve boşlukta hareket birlikte değerlendirilmelidir.","q":"Askı delikleri büyük seçilebilir mi?"},{"a":"Hacmi gösterebilir; denge veya salınım sonucunu gerçek ürüne doğrudan aktarmayın.","q":"İçi boş numune anlamlı mı?"}],"editorial":{"answer":"STL, OBJ, 3MF, STEP/STP veya IGES/IGS dosyanızı teklif alanında açarak dış ölçülerini kontrol edebilirsiniz. Önizleme bir üretim onayı değildir; malzeme, adet ve kullanım koşulları incelendikten sonra baskı kapsamı ve teslim takvimi belirlenir.","sources":[{"url":"https://atasehir.gov.tr/tarihi-ve-cografi-yapisi","title":"Ataşehir Kaymakamlığı — Tarihi ve Coğrafi Yapısı"},{"url":"https://zabita.ibb.gov.tr/birimlerimiz/anadolu-yakasi-zabita-mudurlugu/","title":"İBB Zabıta Daire Başkanlığı — Anadolu Yakası Zabıta Müdürlüğü"}],"takeaways":["Dosyanızı çevrim içi paylaşın; numune gönderimini önceden görüşün.","Kadıköy teslim adresini ve ihtiyaç duyduğunuz tarihi talebe ekleyin.","Üretim ve taşıma sürelerini ayrı planlayın; elden teslim için Ataşehir’den randevu alın."],"relatedPaths":["/3d-baski","/bolgeler/istanbul","/cozumler/urun-gelistirme-prototipleri"]},"local_context":"Kadıköy’den gelen 3D baskı talepleri, Ataşehir Örnek Mahallesi’ndeki çalışma noktamızda değerlendirilir. Dosyanızı çevrim içi paylaşabilir; fiziksel numune için kurye, kargo veya randevuyla elden getirme seçeneğini görüşebilirsiniz. Kadıköy’de ayrı bir şube bulunduğu anlamına gelmez."}}]'::jsonb) ORDER BY value->>'path' LOOP
    SELECT * INTO STRICT current_row FROM public.landing_pages
      WHERE tenant_id='10000000-0000-4000-8000-000000000001' AND path=entry->>'path' FOR UPDATE;
    target_doc := to_jsonb(current_row) || (entry->'patch');
    current_hash := public.publication_payload_hash(to_jsonb(current_row));
    target_hash := public.publication_payload_hash(target_doc);
    IF current_hash <> entry->>'expected_payload_hash' AND current_hash <> target_hash THEN
      RAISE EXCEPTION 'Reviewed baseline changed for %. Re-read and review before applying.',entry->>'path';
    END IF;
    INSERT INTO public.publication_reviews(tenant_id,path,collection,payload_hash,manifest_hash,report)
      VALUES(current_row.tenant_id,current_row.path,'landing_pages',target_hash,review_report->>'sourceHash',review_report)
      ON CONFLICT(tenant_id,collection,path) DO UPDATE
        SET payload_hash=EXCLUDED.payload_hash,manifest_hash=EXCLUDED.manifest_hash,report=EXCLUDED.report,approved_at=now()
        WHERE publication_reviews.tenant_id='10000000-0000-4000-8000-000000000001'
          AND publication_reviews.tenant_id=EXCLUDED.tenant_id
          AND publication_reviews.path=EXCLUDED.path AND publication_reviews.collection=EXCLUDED.collection
          AND (publication_reviews.payload_hash IS DISTINCT FROM EXCLUDED.payload_hash
            OR publication_reviews.manifest_hash IS DISTINCT FROM EXCLUDED.manifest_hash);
    IF current_hash <> target_hash THEN
      UPDATE public.landing_pages SET
        title=target_doc->>'title',summary=target_doc->>'summary',sections=target_doc->'sections',
        faq=target_doc->'faq',editorial=target_doc->'editorial',local_context=target_doc->>'local_context',updated_at=now()
        WHERE id=current_row.id AND tenant_id=current_row.tenant_id;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.landing_pages p JOIN public.publication_reviews r
      ON r.tenant_id=p.tenant_id AND r.path=p.path AND r.collection='landing_pages'
      WHERE p.id=current_row.id AND p.status=current_row.status
        AND public.publication_payload_hash(to_jsonb(p))=target_hash AND r.payload_hash=target_hash) THEN
      RAISE EXCEPTION 'Brand publication verification failed for %',entry->>'path';
    END IF;
  END LOOP;
END $brand_pages$;
COMMIT;
